transforms.pre:
(
  $formatMesure := | $ | {"unitId": $coalesce([unitId, unit.id])}, ["unit"] |;
  $id := $coalesce([$metadata.urlParameters.id, $cuid()]);
  $data := $components.Form2.data~> | $ | {
    "defaultQuantityUnitId": defaultQuantityUnit.id? defaultQuantityUnit.id : null, 
    "barcodeDesignId": barcodeDesign.id? barcodeDesign.id : null,
    "productCategoryId": productCategory.id? productCategory.id : null,
    "width": $formatMesure(width),
    "length": $formatMesure(length),
    "height": $formatMesure(height),
    "weight": $formatMesure(weight),
    "active": true
    }, 
    ["barcodeDesign", "defaultQuantityUnit", "id", "total", "edges", "productCategory"] |;

  {
    "payload":{
      "where":{ "id": $id },
      "update": $data,
      "create": $data
    }
  }
)
